// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address newOwnerCandidate) public {
        vm.assume(newOwnerCandidate != address(0));
        address currentOwner = c.owner();
        vm.prank(currentOwner);
        c.transferOwnership(newOwnerCandidate);

        vm.prank(newOwnerCandidate);
        bool ok;
        try c.owned() { ok = true; } catch { ok = false; }

        assertTrue(ok);
    }
}
